WITH valid AS (SELECT *, CASE WHEN event_type = 'page_view' THEN 1 ELSE 0 END AS is_page_view, COALESCE(page, 'OTHER') AS page_filled FROM web_events WHERE page IS NOT NULL AND session_id IN (4, 9, 24, 37)), latest AS (SELECT * FROM valid QUALIFY ROW_NUMBER() OVER (PARTITION BY page, session_id ORDER BY duration_sec, id) = 1), with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS session_start_flag FROM latest), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps), scored AS (SELECT *, AVG(burst_id) OVER w_part AS burst_id_avg_5, AVG(is_page_view) OVER w_grp AS is_page_view_avg_7d, AVG(duration_sec) OVER (PARTITION BY page ORDER BY burst_id, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS duration_sec_avg_6, PERCENT_RANK() OVER (PARTITION BY session_id, page ORDER BY burst_id DESC) AS burst_id_percent_rank FROM sessionized WHERE is_page_view <= 78 WINDOW w_part AS (ORDER BY is_page_view, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW), w_grp AS (PARTITION BY page ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW)), stats AS (SELECT CASE WHEN duration_sec >= 407 THEN 'HIGH' ELSE 'LOW' END AS duration_sec_tier, burst_id, SUM(CASE WHEN event_type = 'purchase' THEN is_page_view ELSE 0 END) AS purchase_is_page_view, SORT_ARRAY(COLLECT_SET(page)) AS page_list, COUNT(*) AS num_rows FROM scored GROUP BY CASE WHEN duration_sec >= 407 THEN 'HIGH' ELSE 'LOW' END, burst_id) SELECT duration_sec_tier, burst_id, purchase_is_page_view, page_list FROM stats ORDER BY duration_sec_tier DESC;
